import{_ as e,c as i,o as t,a2 as o}from"./chunks/framework.mqLGQ42V.js";const g=JSON.parse('{"title":"音频事件 (Audio Events) - Rive 编辑器","description":"编辑器 (Editor) 在动画中触发音频播放。","frontmatter":{"title":"音频事件 (Audio Events) - Rive 编辑器","description":"编辑器 (Editor) 在动画中触发音频播放。","head":[["meta",{"name":"keywords","content":"Rive, Rive 中文文档, Rive 编辑器, 事件, 音频事件"}]]},"headers":[],"relativePath":"editor/events/audio-events.md","filePath":"editor/events/audio-events.md","lastUpdated":1774838907000}'),r={name:"editor/events/audio-events.md"};function l(n,a,s,d,h,u){return t(),i("div",null,[...a[0]||(a[0]=[o('<p>编辑器 (Editor)</p><h1 id="音频事件-audio-events" tabindex="-1">音频事件 (Audio Events) <a class="header-anchor" href="#音频事件-audio-events" aria-label="Permalink to &quot;音频事件 (Audio Events)&quot;">​</a></h1><p>在动画中触发音频播放。</p><h2 id="​-概览" tabindex="-1"><a href="#overview">​</a> 概览 <a class="header-anchor" href="#​-概览" aria-label="Permalink to &quot;[​](#overview) 概览&quot;">​</a></h2><p>音频事件允许你在动画特定时刻播放声音效果或背景音乐。这对于创建沉浸式交互体验非常有用。</p><h2 id="​-音频资源" tabindex="-1"><a href="#audio-assets">​</a> 音频资源 <a class="header-anchor" href="#​-音频资源" aria-label="Permalink to &quot;[​](#audio-assets) 音频资源&quot;">​</a></h2><h3 id="导入音频" tabindex="-1">导入音频 <a class="header-anchor" href="#导入音频" aria-label="Permalink to &quot;导入音频&quot;">​</a></h3><ol><li>打开 <strong>Assets</strong> 面板</li><li>点击 <strong>+</strong> 按钮或拖放音频文件</li><li>支持的格式：<strong>MP3</strong>、<strong>WAV</strong>、<strong>OGG</strong></li></ol><h3 id="soundly-集成" tabindex="-1">Soundly 集成 <a class="header-anchor" href="#soundly-集成" aria-label="Permalink to &quot;Soundly 集成&quot;">​</a></h3><p>Rive 与 <a href="https://getsoundly.com/" target="_blank" rel="noreferrer">Soundly</a> 集成，可以直接在编辑器中搜索和使用音效。</p><h3 id="创建片段" tabindex="-1">创建片段 <a class="header-anchor" href="#创建片段" aria-label="Permalink to &quot;创建片段&quot;">​</a></h3><p>导入音频后，你可以创建多个片段来使用音频的不同部分：</p><ol><li>选择音频资源</li><li>在检查器中点击 <strong>Create Clip</strong></li><li>设置开始和结束时间</li></ol><h3 id="设置音量" tabindex="-1">设置音量 <a class="header-anchor" href="#设置音量" aria-label="Permalink to &quot;设置音量&quot;">​</a></h3><p>每个音频片段可以单独设置音量：</p><ul><li>在检查器中调整 <strong>Volume</strong> 滑块</li><li>范围：0% (静音) 到 100% (最大)</li></ul><h3 id="导出选项" tabindex="-1">导出选项 <a class="header-anchor" href="#导出选项" aria-label="Permalink to &quot;导出选项&quot;">​</a></h3><p>与其他资源一样，音频可以选择导出方式：</p><ul><li><strong>Embedded (嵌入)</strong>：音频包含在 .riv 文件中</li><li><strong>Referenced (引用)</strong>：音频在运行时单独加载</li><li><strong>Hosted (托管)</strong>：音频从 Rive CDN 加载</li></ul><h2 id="​-创建音频事件" tabindex="-1"><a href="#creating-an-audio-event">​</a> 创建音频事件 <a class="header-anchor" href="#​-创建音频事件" aria-label="Permalink to &quot;[​](#creating-an-audio-event) 创建音频事件&quot;">​</a></h2><ol><li>在 <strong>Events</strong> 面板中创建新事件</li><li>选择事件类型为 <strong>Audio</strong></li><li>从资源中选择要播放的音频片段</li><li>配置播放选项： <ul><li><strong>Loop (循环)</strong>：是否重复播放</li><li><strong>Volume (音量)</strong>：播放音量</li></ul></li></ol><h2 id="​-触发音频事件" tabindex="-1"><a href="#triggering-an-audio-event">​</a> 触发音频事件 <a class="header-anchor" href="#​-触发音频事件" aria-label="Permalink to &quot;[​](#triggering-an-audio-event) 触发音频事件&quot;">​</a></h2><h3 id="通过状态机" tabindex="-1">通过状态机 <a class="header-anchor" href="#通过状态机" aria-label="Permalink to &quot;通过状态机&quot;">​</a></h3><ol><li>在状态机的过渡或状态中添加事件触发器</li><li>选择你创建的音频事件</li><li>设置触发条件</li></ol><h3 id="通过动画关键帧" tabindex="-1">通过动画关键帧 <a class="header-anchor" href="#通过动画关键帧" aria-label="Permalink to &quot;通过动画关键帧&quot;">​</a></h3><ol><li>在时间轴上选择要触发事件的帧</li><li>添加事件关键帧</li><li>选择音频事件</li></ol><h2 id="​-监控音频" tabindex="-1"><a href="#monitoring-audio">​</a> 监控音频 <a class="header-anchor" href="#​-监控音频" aria-label="Permalink to &quot;[​](#monitoring-audio) 监控音频&quot;">​</a></h2><p>在编辑器底部的音频监视器中，你可以：</p><ul><li>查看当前播放的音频</li><li>调整主音量</li><li>静音/取消静音</li></ul><h2 id="​-运行时注意事项" tabindex="-1"><a href="#runtime-considerations">​</a> 运行时注意事项 <a class="header-anchor" href="#​-运行时注意事项" aria-label="Permalink to &quot;[​](#runtime-considerations) 运行时注意事项&quot;">​</a></h2><ul><li>某些平台可能需要用户交互才能播放音频（浏览器策略）</li><li>确保在运行时正确加载音频资源</li><li>考虑为不同平台使用不同的音频格式以优化兼容性</li></ul><p><a href="/docs/editor/events">事件 (Events)</a><a href="/docs/runtimes/rive-events">Rive 事件 (运行时)</a></p>',32)])])}const v=e(r,[["render",l]]);export{g as __pageData,v as default};
